/**
 * S4-T6 / VER-05: Couch verdict recording + --all gate.
 *
 * recordCouchVerdict persists per-route (true|off|wrong) + overall pass/fail.
 * A single 'wrong' forces overall fail (reject pass).
 * couchGateStatus / runAllWaterfall block full-batch until overallVerdict=pass.
 */

import { ConvexError, v } from 'convex/values'
import { api, internal } from './_generated/api'
import { action, internalMutation, mutation, query } from './_generated/server'
import { geospatial } from './geospatialIndex'
import { requireFounder, requireIdentity, requireOperator } from './guards'

const routeVerdictValidator = v.object({
  routeId: v.string(),
  verdict: v.union(v.literal('true'), v.literal('off'), v.literal('wrong')),
})

export type RouteVerdict = {
  routeId: string
  verdict: 'true' | 'off' | 'wrong'
}

/**
 * Pure rule: any 'wrong' route forces overall fail.
 * Pass + wrong is illegal (fabricated-but-passing).
 */
export function resolveOverallVerdict(
  overallVerdict: 'pass' | 'fail',
  routeVerdicts: RouteVerdict[],
): { overallVerdict: 'pass' | 'fail'; rejected: boolean; reason: string | null } {
  const hasWrong = routeVerdicts.some((r) => r.verdict === 'wrong')
  if (hasWrong && overallVerdict === 'pass') {
    return {
      overallVerdict: 'fail',
      rejected: true,
      reason: 'Cannot pass couch gate with any routeVerdict=wrong (fabricated-but-passing)',
    }
  }
  if (hasWrong) {
    return { overallVerdict: 'fail', rejected: false, reason: null }
  }
  return { overallVerdict, rejected: false, reason: null }
}

// ---------------------------------------------------------------------------
// recordCouchVerdict
// ---------------------------------------------------------------------------

export const recordCouchVerdict = mutation({
  args: {
    sampleId: v.string(),
    overallVerdict: v.union(v.literal('pass'), v.literal('fail')),
    routeVerdicts: v.array(routeVerdictValidator),
  },
  handler: async (ctx, { sampleId, overallVerdict, routeVerdicts }) => {
    const identity = await requireOperator(ctx)

    if (routeVerdicts.length === 0) {
      throw new ConvexError({
        code: 'EMPTY_ROUTE_VERDICTS',
        message: 'routeVerdicts must not be empty',
      })
    }

    // FIX-03/04: Load frozen manifest — reject if not found or not frozen
    const manifest = await ctx.db
      .query('couch_samples')
      .withIndex('by_sampleId', (q) => q.eq('sampleId', sampleId))
      .first()

    if (!manifest) {
      throw new ConvexError({
        code: 'MANIFEST_NOT_FOUND',
        message: `No couch sample found for sampleId '${sampleId}' — verdict requires a frozen manifest`,
      })
    }

    if (manifest.status !== 'frozen') {
      throw new ConvexError({
        code: 'MANIFEST_NOT_FROZEN',
        message: `Couch sample '${sampleId}' status is '${manifest.status ?? 'draft'}', not 'frozen' — verdict requires a frozen immutable manifest`,
      })
    }

    // FIX-03/04: Verify exact membership (same set, no missing, no extras, no duplicates)
    const manifestRouteIds = new Set((manifest.routes ?? []).map((r: any) => r.routeId))
    const verdictRouteIds = new Set(routeVerdicts.map((r) => r.routeId))

    // Check for missing routes (in manifest but not in verdict)
    const missing = [...manifestRouteIds].filter((id) => !verdictRouteIds.has(id))
    if (missing.length > 0) {
      throw new ConvexError({
        code: 'VERDICT_MISSING_ROUTES',
        message: `Verdict is missing ${missing.length} route(s) from the frozen manifest: ${missing.slice(0, 3).join(', ')}${missing.length > 3 ? '...' : ''}`,
      })
    }

    // Check for extra routes (in verdict but not in manifest)
    const extra = [...verdictRouteIds].filter((id) => !manifestRouteIds.has(id))
    if (extra.length > 0) {
      throw new ConvexError({
        code: 'VERDICT_EXTRA_ROUTES',
        message: `Verdict contains ${extra.length} route(s) not in the frozen manifest: ${extra.slice(0, 3).join(', ')}${extra.length > 3 ? '...' : ''}`,
      })
    }

    // Check for duplicate routeIds in verdict
    if (verdictRouteIds.size !== routeVerdicts.length) {
      throw new ConvexError({
        code: 'VERDICT_DUPLICATE_ROUTES',
        message: 'Verdict contains duplicate routeIds — each route must have exactly one verdict',
      })
    }

    const resolved = resolveOverallVerdict(overallVerdict, routeVerdicts)
    if (resolved.rejected) {
      throw new ConvexError({
        code: 'WRONG_FORCES_FAIL',
        message: resolved.reason ?? 'wrong forces fail',
      })
    }

    // FIX-03/04: APPEND-ONLY — always INSERT a new verdict, never replace
    const doc = {
      sampleId,
      overallVerdict: resolved.overallVerdict,
      routeVerdicts,
      recordedAt: Date.now(),
      recordedBy: identity.clerkUserId,
      // FIX-03/04: Bind to frozen manifest
      manifestHash: manifest.manifestHash,
      catalogVersion: manifest.catalogVersion,
    }

    await ctx.db.insert('couch_verdicts', doc)

    return {
      sampleId,
      overallVerdict: resolved.overallVerdict,
      routeVerdicts,
      recordedAt: doc.recordedAt,
      recordedBy: doc.recordedBy,
      manifestHash: doc.manifestHash,
      catalogVersion: doc.catalogVersion,
    }
  },
})

export const getCouchVerdict = query({
  args: {
    sampleId: v.optional(v.string()),
  },
  handler: async (ctx, { sampleId }) => {
    await requireIdentity(ctx)
    if (sampleId) {
      // FIX-03/04: APPEND-ONLY — return latest verdict by recordedAt for this sampleId
      const rows = await ctx.db
        .query('couch_verdicts')
        .withIndex('by_sampleId', (q) => q.eq('sampleId', sampleId))
        .take(100)
      if (rows.length === 0) return null
      return rows.sort((a, b) => b.recordedAt - a.recordedAt)[0]
    }
    // Latest by recordedAt across all samples
    const rows = await ctx.db.query('couch_verdicts').take(50)
    if (rows.length === 0) return null
    return rows.sort((a, b) => b.recordedAt - a.recordedAt)[0]
  },
})

/**
 * Gate status for full-batch (--all).
 *
 * FIX-03/04: Only allowed when the latest pass verdict is bound to a CURRENT
 * active/frozen manifest whose catalogVersion matches the live catalog.
 * If the manifest's geometry/catalog version has drifted since the verdict, block.
 */
export const couchGateStatus = query({
  args: {},
  handler: async (ctx) => {
    await requireIdentity(ctx)
    const passes = await ctx.db
      .query('couch_verdicts')
      .withIndex('by_overallVerdict', (q) => q.eq('overallVerdict', 'pass'))
      .take(10)

    if (passes.length === 0) {
      return {
        allowed: false,
        overallVerdict: null as 'pass' | 'fail' | null,
        reason: 'Couch gate blocked: no recordCouchVerdict({overallVerdict:"pass"}) yet',
        sampleId: null as string | null,
        manifestHash: null as string | null,
      }
    }

    // Latest pass verdict
    const latest = passes.sort((a, b) => b.recordedAt - a.recordedAt)[0]

    // FIX-03/04: Verify the verdict is bound to a still-frozen manifest
    const manifest = await ctx.db
      .query('couch_samples')
      .withIndex('by_sampleId', (q) => q.eq('sampleId', latest.sampleId))
      .first()

    if (!manifest || manifest.status !== 'frozen') {
      return {
        allowed: false,
        overallVerdict: null,
        reason: 'Couch gate blocked: bound manifest is no longer frozen or does not exist',
        sampleId: latest.sampleId,
        manifestHash: latest.manifestHash ?? null,
      }
    }

    // FIX-03/04: Check catalog version hasn't drifted
    const currentCatalogVersion = 's4-trust-pipeline-v1'
    if (latest.catalogVersion && latest.catalogVersion !== currentCatalogVersion) {
      return {
        allowed: false,
        overallVerdict: null,
        reason: `Couch gate blocked: catalog version drift — verdict bound to '${latest.catalogVersion}', current catalog is '${currentCatalogVersion}'`,
        sampleId: latest.sampleId,
        manifestHash: latest.manifestHash ?? null,
      }
    }

    // FIX-03/04: Verify manifestHash matches current frozen manifest
    if (
      latest.manifestHash &&
      manifest.manifestHash &&
      latest.manifestHash !== manifest.manifestHash
    ) {
      return {
        allowed: false,
        overallVerdict: null,
        reason:
          'Couch gate blocked: manifest hash mismatch — the frozen manifest has changed since this verdict was recorded',
        sampleId: latest.sampleId,
        manifestHash: latest.manifestHash,
      }
    }

    return {
      allowed: true,
      overallVerdict: 'pass' as const,
      reason: null as string | null,
      sampleId: latest.sampleId,
      recordedAt: latest.recordedAt,
      manifestHash: latest.manifestHash ?? null,
    }
  },
})

/**
 * FIX-08: Clear couch verdicts — internalMutation.
 * Use clearCouchVerdictsPublic instead.
 */
export const clearCouchVerdicts = internalMutation({
  args: {},
  handler: async (ctx) => {
    const rows = await ctx.db.query('couch_verdicts').take(100)
    for (const r of rows) {
      await ctx.db.delete(r._id)
    }
    return { cleared: rows.length }
  },
})

/** FIX-08: Public founder-gated wrapper for clearCouchVerdicts. */
export const clearCouchVerdictsPublic = mutation({
  args: {},
  handler: async (ctx): Promise<{ cleared: number }> => {
    await requireFounder(ctx)
    const result: { cleared: number } = await ctx.runMutation(
      internal.couchVerdict.clearCouchVerdicts,
      {},
    )
    return result
  },
})

// ---------------------------------------------------------------------------
// --all waterfall gate (blocks until couch pass)
// ---------------------------------------------------------------------------

const POLY_41MI =
  'oditE~o~}Uk~@uq@i~@uq@k~@uq@k~@uq@i~@uq@k~@sq@i~@uq@k~@uq@k~@uq@i~@uq@k~@uq@k~@uq@i~@uq@k~@uq@i~@uq@k~@sq@k~@uq@i~@uq@k~@uq@k~@uq@i~@uq@k~@uq@k~@uq@i~@uq@k~@uq@i~@uq@k~@sq@k~@uq@k~@uq@i~@uq@k~@uq@k~@uq@i~@uq@k~@uq@i~@uq@k~@uq@k~@uq@i~@sq@k~@uq@'

const ALL_BATCH_PREFIX = 'test:couch-all-'

export const seedAllBatchFixtures = internalMutation({
  args: {},
  handler: async (ctx) => {
    const routeId = `${ALL_BATCH_PREFIX}001`
    const existing = await ctx.db
      .query('curated_routes')
      .withIndex('by_routeId', (q) => q.eq('routeId', routeId))
      .first()

    const centroidLat = 35.1
    const centroidLng = -120.5
    const nowMs = Date.now()
    const base = {
      name: 'Couch All Batch 001',
      lengthMiles: 41,
      centroidLat,
      centroidLng,
      boundsNeLat: centroidLat + 0.3,
      boundsNeLng: centroidLng + 0.3,
      boundsSwLat: centroidLat - 0.3,
      boundsSwLng: centroidLng - 0.3,
      location: { type: 'Point' as const, coordinates: [centroidLng, centroidLat] },
      compositeScore: 85,
      curvatureScore: 90,
      scenicScore: 80,
      technicalScore: 85,
      trafficScore: 75,
      remotenessScore: 70,
      routePolyline: POLY_41MI,
      geometryStatus: 'unresolved' as const,
      geometryProvenance: undefined,
      riderReady: false,
      state: 'California',
      summary: 'S4-T6 --all gate fixture with scrapable polyline for Lever 1.',
      retiredAt: undefined,
      duplicateOf: undefined,
      quarantine: undefined,
    }

    if (existing) {
      // Clear prior geometry so waterfall actually runs levers
      const geom = await ctx.db
        .query('curated_route_geometry')
        .withIndex('by_routeId', (q) => q.eq('routeId', routeId))
        .first()
      if (geom) await ctx.db.delete(geom._id)
      await ctx.db.patch(existing._id, base)
      return { routeId, created: false }
    }

    const docId = await ctx.db.insert('curated_routes', {
      routeId,
      source: 'editorial',
      primaryArchetype: 'twisties',
      secondaryTags: ['test', 's4t6', 'all-batch'],
      oneLiner: 'Couch all-batch fixture',
      badges: [],
      season: 'year_round',
      contentVersion: 1,
      seededAt: nowMs,
      rideWorthiness: {
        verdict: 'ride' as const,
        reason: 's4t6 all-batch seed',
        model: 'test',
        classifiedAt: nowMs,
      },
      ...base,
    })

    try {
      await geospatial.insert(
        ctx,
        docId,
        { latitude: centroidLat, longitude: centroidLng },
        { state: 'California', primaryArchetype: 'twisties' },
        85,
      )
    } catch {
      /* index may exist */
    }

    return { routeId, created: true }
  },
})

export const teardownAllBatchFixtures = internalMutation({
  args: {},
  handler: async (ctx) => {
    const removed: string[] = []
    for (const status of ['generated', 'unresolved', 'review', 'failed'] as const) {
      const rows = await ctx.db
        .query('curated_routes')
        .withIndex('by_geometry_status', (q) => q.eq('geometryStatus', status))
        .take(100)
      for (const row of rows) {
        if (!row.routeId.startsWith(ALL_BATCH_PREFIX)) continue
        const geom = await ctx.db
          .query('curated_route_geometry')
          .withIndex('by_routeId', (q) => q.eq('routeId', row.routeId))
          .first()
        if (geom) await ctx.db.delete(geom._id)
        try {
          await geospatial.remove(ctx, row._id)
        } catch {
          /* ok */
        }
        await ctx.db.delete(row._id)
        removed.push(row.routeId)
      }
    }
    return { removed, count: removed.length }
  },
})

/** FIX-08: Public founder-gated wrappers for all-batch fixtures. */
export const seedAllBatchFixturesPublic = mutation({
  args: {},
  handler: async (ctx): Promise<{ routeId: string; created: boolean }> => {
    await requireFounder(ctx)
    const result: { routeId: string; created: boolean } = await ctx.runMutation(
      internal.couchVerdict.seedAllBatchFixtures,
      {},
    )
    return result
  },
})

export const teardownAllBatchFixturesPublic = mutation({
  args: {},
  handler: async (ctx): Promise<{ removed: string[]; count: number }> => {
    await requireFounder(ctx)
    const result: { removed: string[]; count: number } = await ctx.runMutation(
      internal.couchVerdict.teardownAllBatchFixtures,
      {},
    )
    return result
  },
})

/**
 * Full-batch entry point. STRICTLY blocked until couchGateStatus.allowed.
 * After pass, delegates to the S4-T5 waterfall orchestrator.
 */
type CouchGateSnapshot = {
  allowed: boolean
  overallVerdict: 'pass' | 'fail' | null
  reason: string | null
  sampleId: string | null
  recordedAt?: number
}

type RunAllWaterfallResult = {
  mode: 'all'
  gate: { allowed: true; overallVerdict: 'pass' | 'fail' | null }
  routes: unknown[]
  processed: number
  skipped: number
  reprocessed: number
  totalCostUsd: number
  maxCostUsd: number | null
  batchStopReason: string | null
  costExceededMessage: string | null
  perLeverCounts: { lever1: number; lever2: number; lever3: number }
  perStateCounts: Record<string, number>
  backoffScheduleSeconds: number[]
  maxRetries: number
}

export const runAllWaterfall = action({
  args: {
    routeIds: v.array(v.string()),
    maxCost: v.optional(v.number()),
  },
  handler: async (ctx, args): Promise<RunAllWaterfallResult> => {
    await requireIdentity(ctx)

    const gate = (await ctx.runQuery(api.couchVerdict.couchGateStatus, {})) as CouchGateSnapshot
    if (!gate.allowed) {
      throw new ConvexError({
        code: 'COUCH_GATE_BLOCKED',
        message:
          gate.reason ??
          'Couch gate blocked --all until recordCouchVerdict({overallVerdict:"pass"})',
      })
    }

    // Reuse S4-T5 waterfall for the gated full batch
    const report = await ctx.runAction(api.waterfallOrchestrator.runSampleWaterfall, {
      routeIds: args.routeIds,
      maxCost: args.maxCost ?? 10,
    })

    return {
      mode: 'all' as const,
      gate: { allowed: true as const, overallVerdict: gate.overallVerdict },
      ...report,
    }
  },
})

text:
/**
 * S4-T6 / VER-05: Couch-sample assembler.
 *
 * Stratifies ~25 recovered routes across provenance types
 * (scraped_promoted, ai_reconstructed, name_routed) and reconstruction
 * difficulty (easy anchor-rich ↔ hard sparse), then exports each as a
 * map PNG + metadata (provenance, routedMiles, claimedMiles).
 */

import { ConvexError, v } from 'convex/values'
import { api, internal } from './_generated/api'
import { action, internalMutation, mutation, query } from './_generated/server'
import { buildFixturePolyline } from './couchRouteMapPng'
import { geospatial } from './geospatialIndex'
import { requireFounder, requireIdentity } from './guards'

// Re-export fixture polyline builder for callers/tests.
export {
  buildFixturePolyline,
  MAP_PNG_HEIGHT,
  MAP_PNG_WIDTH,
  MIN_PNG_BASE64,
} from './couchRouteMapPng'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

export const COUCH_SAMPLE_TARGET = 25
export const COUCH_SAMPLE_MIN = 20
export const COUCH_SAMPLE_MAX = 30
export const MIN_PER_PROVENANCE = 5
export const COUCH_ROUTE_PREFIX = 'test:couch-'

export type Provenance = 'scraped_promoted' | 'ai_reconstructed' | 'name_routed'
export type Difficulty = 'easy' | 'medium' | 'hard'

export type CouchSampleRoute = {
  routeId: string
  provenance: Provenance
  anchorCount: number
  claimedMiles: number | null
  routedMiles: number
  difficulty: Difficulty
  descriptionLength: number
}

const PROVENANCES: Provenance[] = ['scraped_promoted', 'ai_reconstructed', 'name_routed']

// ---------------------------------------------------------------------------
// Pure stratification helpers (unit-testable)
// ---------------------------------------------------------------------------

export function classifyDifficulty(anchorCount: number, descriptionLength: number): Difficulty {
  if (anchorCount >= 7 && descriptionLength >= 80) return 'easy'
  if (anchorCount <= 3 || descriptionLength < 40) return 'hard'
  return 'medium'
}

/**
 * Stratify candidates into ~targetSize routes with:
 *  - ≥ MIN_PER_PROVENANCE of each provenance
 *  - difficulty range (at least one easy, one hard when available)
 */
export function stratifyCouchSample(
  candidates: CouchSampleRoute[],
  targetSize: number = COUCH_SAMPLE_TARGET,
): CouchSampleRoute[] {
  const size = Math.min(COUCH_SAMPLE_MAX, Math.max(COUCH_SAMPLE_MIN, targetSize))
  const byProv: Record<Provenance, CouchSampleRoute[]> = {
    scraped_promoted: [],
    ai_reconstructed: [],
    name_routed: [],
  }
  for (const c of candidates) {
    if (c.provenance in byProv) byProv[c.provenance].push(c)
  }

  // Prefer diversity within each provenance: sort hard → easy by anchor count spread
  for (const p of PROVENANCES) {
    byProv[p].sort((a, b) => a.anchorCount - b.anchorCount)
  }

  const picked = new Map<string, CouchSampleRoute>()

  // Round-robin minimum per provenance
  for (const p of PROVENANCES) {
    const pool = byProv[p]
    // Take extremes first (hard + easy) then fill
    const ordered = diversifyByDifficulty(pool)
    for (let i = 0; i < Math.min(MIN_PER_PROVENANCE, ordered.length); i++) {
      picked.set(ordered[i].routeId, ordered[i])
    }
  }

  // Ensure hard + easy representation globally when available
  const all = candidates.filter((c) => !picked.has(c.routeId))
  const hard = all.find((c) => c.difficulty === 'hard')
  const easy = all.find((c) => c.difficulty === 'easy')
  if (hard) picked.set(hard.routeId, hard)
  if (easy) picked.set(easy.routeId, easy)

  // Fill remaining slots round-robin across provenances
  let guard = 0
  while (picked.size < size && guard < candidates.length * 3) {
    guard += 1
    let added = false
    for (const p of PROVENANCES) {
      if (picked.size >= size) break
      const next = byProv[p].find((c) => !picked.has(c.routeId))
      if (next) {
        picked.set(next.routeId, next)
        added = true
      }
    }
    if (!added) break
  }

  return Array.from(picked.values()).slice(0, size)
}

function diversifyByDifficulty(pool: CouchSampleRoute[]): CouchSampleRoute[] {
  if (pool.length <= 2) return [...pool]
  const hard = pool.filter((c) => c.difficulty === 'hard')
  const easy = pool.filter((c) => c.difficulty === 'easy')
  const med = pool.filter((c) => c.difficulty === 'medium')
  const out: CouchSampleRoute[] = []
  const queues = [hard, easy, med]
  let i = 0
  while (out.length < pool.length) {
    const q = queues[i % queues.length]
    const next = q.shift()
    if (next) out.push(next)
    i += 1
    if (queues.every((x) => x.length === 0)) break
  }
  return out
}

// ---------------------------------------------------------------------------
// Server-side hash helpers (FIX-10)
// ---------------------------------------------------------------------------

/**
 * Compute a SHA-256 hash as a hex string.
 * Uses the Convex V8 runtime's global crypto.subtle.
 */
async function sha256Hex(input: string): Promise<string> {
  const encoder = new TextEncoder()
  const data = encoder.encode(input)
  const hashBuffer = await crypto.subtle.digest('SHA-256', data)
  const hashArray = Array.from(new Uint8Array(hashBuffer))
  return hashArray.map((b) => b.toString(16).padStart(2, '0')).join('')
}

/**
 * Compute a per-route geometry hash from the curated_route_geometry record.
 * Uses: routeId + geometry value + verification verdict + provenance.
 */
function computeRouteGeometryHash(routeId: string, geom: any): string {
  const parts = [
    routeId,
    geom?.value ?? '',
    geom?.verification?.verdict ?? '',
    geom?.provenance ?? '',
  ]
  return parts.join('::')
}

/**
 * Compute the manifest hash: SHA-256 of sorted routeIds + per-route geometry
 * hashes + catalogVersion.
 */
async function computeManifestHash(
  routes: Array<{ routeId: string }>,
  routeGeometryHashes: Record<string, string>,
  catalogVersion: string,
): Promise<string> {
  const sortedRouteIds = [...routes.map((r) => r.routeId)].sort()
  const parts = sortedRouteIds.map((rid) => `${rid}:${routeGeometryHashes[rid] ?? 'MISSING'}`)
  parts.push(`catalog:${catalogVersion}`)
  return sha256Hex(parts.join('|'))
}

// ---------------------------------------------------------------------------
// Fixture seed / teardown
// ---------------------------------------------------------------------------

type SeedSpec = {
  routeId: string
  provenance: Provenance
  anchorCount: number
  claimedMiles: number
  routedMiles: number
  summary: string
  name: string
}

function buildSeedSpecs(): SeedSpec[] {
  const specs: SeedSpec[] = []

  // Explicit PRD fixtures
  specs.push({
    routeId: 'test:scraped-1',
    provenance: 'scraped_promoted',
    anchorCount: 5,
    claimedMiles: 41,
    routedMiles: 41,
    summary:
      'Foxen Canyon Road scenic loop through Santa Maria wine country with five named anchors.',
    name: 'Scraped Promoted Fixture 1',
  })
  specs.push({
    routeId: 'test:ai-recon-1',
    provenance: 'ai_reconstructed',
    // AC-3 seeded lengths: routedMiles 41.1, claimedMiles 41
    anchorCount: 7,
    claimedMiles: 41,
    routedMiles: 41.1,
    summary:
      'Highway 101 in Santa Maria, CA. Exit Betteravia Road heading East. Betteravia becomes Foxen Canyon. Follow canyon roads north to highway 166 then west to 101. Anchor-rich reconstruction with clear narrative.',
    name: 'AI Reconstructed Fixture 1',
  })
  specs.push({
    routeId: 'test:name-routed-1',
    provenance: 'name_routed',
    anchorCount: 2,
    claimedMiles: 25,
    routedMiles: 25,
    summary: 'Sparse.',
    name: 'Name Routed Fixture 1',
  })

  // Pad to ≥10 per provenance with difficulty range (anchorCount 2..15)
  const pad: Array<{ provenance: Provenance; base: string }> = [
    { provenance: 'scraped_promoted', base: `${COUCH_ROUTE_PREFIX}scraped` },
    { provenance: 'ai_reconstructed', base: `${COUCH_ROUTE_PREFIX}ai` },
    { provenance: 'name_routed', base: `${COUCH_ROUTE_PREFIX}name` },
  ]

  for (const { provenance, base } of pad) {
    for (let i = 0; i < 9; i++) {
      // Cycle difficulty: hard (2-3), medium (4-6), easy (7-15)
      let anchorCount: number
      let summary: string
      if (i % 3 === 0) {
        anchorCount = 2 + (i % 2) // 2 or 3
        summary = 'Short sparse.'
      } else if (i % 3 === 1) {
        anchorCount = 4 + (i % 3) // 4-6
        summary =
          'A medium-length description of the mountain loop with a few named roads and towns.'
      } else {
        anchorCount = 7 + (i % 5) // 7-11
        summary =
          'Highway 101 corridor scenic run with many named waypoints, canyon roads, mesa junctions, and clear turn-by-turn narrative for reconstruction. Anchor-rich easy case with detailed landmarks throughout the valley.'
      }
      const claimed = 20 + i * 3
      // Keep one ai route with the special 41.1/41 pair (already seeded as test:ai-recon-1)
      const routed = claimed + (i % 5 === 0 ? 0.5 : 0)
      specs.push({
        routeId: `${base}-${String(i).padStart(3, '0')}`,
        provenance,
        anchorCount,
        claimedMiles: claimed,
        routedMiles: routed,
        summary,
        name: `Couch ${provenance} ${i}`,
      })
    }
  }

  return specs
}

async function upsertCouchRoute(
  ctx: any,
  spec: SeedSpec,
): Promise<{ routeId: string; created: boolean }> {
  const existing = await ctx.db
    .query('curated_routes')
    .withIndex('by_routeId', (q: any) => q.eq('routeId', spec.routeId))
    .first()

  // Distinct centroid + polyline per routeId so rendered map PNGs differ.
  const centroidLat = 34.95 + (spec.anchorCount % 10) * 0.01 + (spec.routeId.length % 7) * 0.003
  const centroidLng =
    -120.42 -
    (spec.anchorCount % 10) * 0.01 -
    (spec.routeId.charCodeAt(spec.routeId.length - 1) % 5) * 0.004
  const nowMs = Date.now()
  const difficulty = classifyDifficulty(spec.anchorCount, spec.summary.length)
  const routePolyline = buildFixturePolyline(spec.routeId, centroidLat, centroidLng)

  const base = {
    name: spec.name,
    lengthMiles: spec.claimedMiles,
    centroidLat,
    centroidLng,
    boundsNeLat: centroidLat + 0.3,
    boundsNeLng: centroidLng + 0.3,
    boundsSwLat: centroidLat - 0.3,
    boundsSwLng: centroidLng - 0.3,
    location: { type: 'Point' as const, coordinates: [centroidLng, centroidLat] },
    compositeScore: 85,
    curvatureScore: 90,
    scenicScore: 80,
    technicalScore: 85,
    trafficScore: 75,
    remotenessScore: 70,
    routePolyline,
    geometryStatus: 'generated' as const,
    geometryProvenance: spec.provenance,
    riderReady: true,
    state: 'California',
    summary: spec.summary,
    retiredAt: undefined,
    duplicateOf: undefined,
    quarantine: undefined,
  }

  let docId = existing?._id
  if (existing) {
    await ctx.db.patch(existing._id, base)
  } else {
    docId = await ctx.db.insert('curated_routes', {
      routeId: spec.routeId,
      source: 'editorial',
      primaryArchetype: 'twisties',
      secondaryTags: ['test', 's4t6', 'couch', difficulty],
      oneLiner: `Couch sample ${spec.provenance}`,
      badges: [],
      season: 'year_round',
      contentVersion: 1,
      seededAt: nowMs,
      rideWorthiness: {
        verdict: 'ride' as const,
        reason: 's4t6 couch seed',
        model: 'test',
        classifiedAt: nowMs,
      },
      ...base,
    })
  }

  const anchors = Array.from({ length: spec.anchorCount }, (_, i) => ({
    lat: centroidLat + i * 0.01,
    lng: centroidLng + i * 0.01,
    formatted: `Anchor ${i + 1}`,
    distanceFromCentroid: i * 0.5,
  }))

  const geomDoc = {
    routeId: spec.routeId,
    format: 'polyline' as const,
    encoding: 'utf-8',
    precision: 5,
    value: routePolyline,
    provenance: spec.provenance,
    verification: {
      routeId: spec.routeId,
      verdict: 'pass' as const,
      provenance: spec.provenance,
      geometry: routePolyline,
      geometryStatus: 'generated' as const,
      anchorCount: spec.anchorCount,
      anchors,
      pointCount: 50 + spec.anchorCount,
      degenerate: false,
      ratio: spec.claimedMiles > 0 ? spec.routedMiles / spec.claimedMiles : null,
      claimedMiles: spec.claimedMiles,
      routedMiles: spec.routedMiles,
    },
  }

  const geom = await ctx.db
    .query('curated_route_geometry')
    .withIndex('by_routeId', (q: any) => q.eq('routeId', spec.routeId))
    .first()
  if (geom) {
    await ctx.db.replace(geom._id, geomDoc)
  } else {
    await ctx.db.insert('curated_route_geometry', geomDoc)
  }

  try {
    await geospatial.insert(
      ctx,
      docId,
      { latitude: centroidLat, longitude: centroidLng },
      { state: 'California', primaryArchetype: 'twisties' },
      85,
    )
  } catch {
    /* may already be indexed */
  }

  return { routeId: spec.routeId, created: !existing }
}

/**
 * FIX-08: Core fixture seeding — internalMutation, not callable from
 * npx convex run by production clients. Use seedCouchFixturesPublic instead.
 */
export const seedCouchFixtures = internalMutation({
  args: {},
  handler: async (ctx) => {
    const specs = buildSeedSpecs()
    const seeded: string[] = []
    for (const spec of specs) {
      const r = await upsertCouchRoute(ctx, spec)
      seeded.push(r.routeId)
    }
    return { seeded, count: seeded.length }
  },
})

/** FIX-08: Public founder-gated wrapper for seedCouchFixtures. */
export const seedCouchFixturesPublic = mutation({
  args: {},
  handler: async (ctx): Promise<{ seeded: string[]; count: number }> => {
    await requireFounder(ctx)
    const result: { seeded: string[]; count: number } = await ctx.runMutation(
      internal.couchSampleAssembler.seedCouchFixtures,
      {},
    )
    return result
  },
})

/**
 * FIX-08: Core fixture teardown — internalMutation.
 */
export const teardownCouchFixtures = internalMutation({
  args: {},
  handler: async (ctx) => {
    const prefixes = [COUCH_ROUTE_PREFIX, 'test:scraped-', 'test:ai-recon-', 'test:name-routed-']
    const removed: string[] = []

    const deleteByRouteId = async (routeId: string) => {
      const doc = await ctx.db
        .query('curated_routes')
        .withIndex('by_routeId', (q: any) => q.eq('routeId', routeId))
        .first()
      if (!doc) return
      const geom = await ctx.db
        .query('curated_route_geometry')
        .withIndex('by_routeId', (q: any) => q.eq('routeId', routeId))
        .first()
      if (geom) await ctx.db.delete(geom._id)
      try {
        await geospatial.remove(ctx, doc._id)
      } catch {
        /* not indexed */
      }
      await ctx.db.delete(doc._id)
      removed.push(routeId)
    }

    for (const status of ['generated', 'unresolved', 'review', 'failed'] as const) {
      const rows = await ctx.db
        .query('curated_routes')
        .withIndex('by_geometry_status', (q: any) => q.eq('geometryStatus', status))
        .take(500)
      for (const row of rows) {
        if (prefixes.some((p) => row.routeId.startsWith(p))) {
          await deleteByRouteId(row.routeId)
        }
      }
    }

    // Drop couch samples for these tests
    const samples = await ctx.db.query('couch_samples').take(50)
    for (const s of samples) {
      if (s.sampleId.startsWith('couch-')) {
        await ctx.db.delete(s._id)
      }
    }

    return { removed, count: removed.length }
  },
})

/** FIX-08: Public founder-gated wrapper for teardownCouchFixtures. */
export const teardownCouchFixturesPublic = mutation({
  args: {},
  handler: async (ctx): Promise<{ removed: string[]; count: number }> => {
    await requireFounder(ctx)
    const result: { removed: string[]; count: number } = await ctx.runMutation(
      internal.couchSampleAssembler.teardownCouchFixtures,
      {},
    )
    return result
  },
})

// ---------------------------------------------------------------------------
// List recovered candidates (internal-ish public query for assembler)
// ---------------------------------------------------------------------------

async function toCandidate(ctx: any, row: any): Promise<CouchSampleRoute | null> {
  const geom = await ctx.db
    .query('curated_route_geometry')
    .withIndex('by_routeId', (q: any) => q.eq('routeId', row.routeId))
    .first()

  const provenance = (geom?.provenance ??
    row.geometryProvenance ??
    geom?.verification?.provenance) as Provenance | undefined
  if (!provenance || !PROVENANCES.includes(provenance)) return null

  const anchorCount = geom?.verification?.anchorCount ?? 2
  const claimedMiles = geom?.verification?.claimedMiles ?? row.lengthMiles ?? null
  const routedMiles = geom?.verification?.routedMiles ?? row.lengthMiles ?? 0
  const descriptionLength = (row.summary ?? row.oneLiner ?? '').length
  const difficulty = classifyDifficulty(anchorCount, descriptionLength)

  return {
    routeId: row.routeId,
    provenance,
    anchorCount,
    claimedMiles,
    routedMiles,
    difficulty,
    descriptionLength,
  }
}

export const listRecoveredCandidates = query({
  args: {
    routeIdPrefix: v.optional(v.string()),
    /** When true (default), look up known couch fixture routeIds by index so
     * they are not lost among a large generated catalog. */
    preferFixtures: v.optional(v.boolean()),
    limit: v.optional(v.number()),
  },
  handler: async (ctx, { routeIdPrefix, preferFixtures, limit }) => {
    await requireIdentity(ctx)
    const take = Math.min(limit ?? 200, 400)
    const candidates: CouchSampleRoute[] = []
    const seen = new Set<string>()

    // Prefer explicit fixture lookups (index by_routeId) — reliable for tests.
    if (preferFixtures !== false) {
      for (const spec of buildSeedSpecs()) {
        if (routeIdPrefix && !spec.routeId.startsWith(routeIdPrefix)) {
          const isPrd =
            spec.routeId.startsWith('test:scraped-') ||
            spec.routeId.startsWith('test:ai-recon-') ||
            spec.routeId.startsWith('test:name-routed-')
          if (!isPrd) continue
        }
        const row = await ctx.db
          .query('curated_routes')
          .withIndex('by_routeId', (q) => q.eq('routeId', spec.routeId))
          .first()
        if (!row || row.geometryStatus !== 'generated') continue
        const c = await toCandidate(ctx, row)
        if (c && !seen.has(c.routeId)) {
          seen.add(c.routeId)
          candidates.push(c)
        }
      }
    }

    // Supplement from generated index when more catalog routes are wanted
    if (candidates.length < take) {
      const rows = await ctx.db
        .query('curated_routes')
        .withIndex('by_geometry_status', (q) => q.eq('geometryStatus', 'generated'))
        .take(take)
      for (const row of rows) {
        if (seen.has(row.routeId)) continue
        if (routeIdPrefix && !row.routeId.startsWith(routeIdPrefix)) continue
        const c = await toCandidate(ctx, row)
        if (c) {
          seen.add(c.routeId)
          candidates.push(c)
        }
      }
    }

    return { candidates, count: candidates.length }
  },
})

export const getCouchSample = query({
  args: { sampleId: v.string() },
  handler: async (ctx, { sampleId }) => {
    await requireIdentity(ctx)
    const row = await ctx.db
      .query('couch_samples')
      .withIndex('by_sampleId', (q) => q.eq('sampleId', sampleId))
      .first()
    return row ?? null
  },
})

export const storeCouchSample = mutation({
  args: {
    sampleId: v.string(),
    routes: v.array(
      v.object({
        routeId: v.string(),
        provenance: v.union(
          v.literal('scraped_promoted'),
          v.literal('ai_reconstructed'),
          v.literal('name_routed'),
        ),
        anchorCount: v.number(),
        claimedMiles: v.union(v.number(), v.null()),
        routedMiles: v.number(),
        difficulty: v.union(v.literal('easy'), v.literal('medium'), v.literal('hard')),
        descriptionLength: v.number(),
      }),
    ),
  },
  handler: async (ctx, { sampleId, routes }) => {
    const identity = await requireIdentity(ctx)

    if (routes.length < COUCH_SAMPLE_MIN || routes.length > COUCH_SAMPLE_MAX) {
      throw new ConvexError({
        code: 'INVALID_SAMPLE_SIZE',
        message: `Couch sample size must be ${COUCH_SAMPLE_MIN}–${COUCH_SAMPLE_MAX}, got ${routes.length}`,
      })
    }

    // FIX-10: Reject duplicate routeIds
    const routeIdSet = new Set(routes.map((r) => r.routeId))
    if (routeIdSet.size !== routes.length) {
      throw new ConvexError({
        code: 'DUPLICATE_ROUTE_IDS',
        message: 'Couch sample contains duplicate routeIds — each route must be unique',
      })
    }

    for (const p of PROVENANCES) {
      const n = routes.filter((r) => r.provenance === p).length
      if (n === 0) {
        throw new ConvexError({
          code: 'UNSTRATIFIED_SAMPLE',
          message: `Couch sample missing provenance ${p}`,
        })
      }
    }

    // FIX-10: Check for existing frozen manifest — reject re-freeze
    const existing = await ctx.db
      .query('couch_samples')
      .withIndex('by_sampleId', (q) => q.eq('sampleId', sampleId))
      .first()

    if (existing?.status === 'frozen') {
      throw new ConvexError({
        code: 'MANIFEST_ALREADY_FROZEN',
        message: `Couch sample ${sampleId} is already frozen — manifest is immutable`,
      })
    }

    // FIX-10: Validate every routeId exists in curated_routes AND has
    // gate-passing geometry (curated_route_geometry.verification.verdict === 'pass').
    const routeGeometryHashes: Record<string, string> = {}
    const catalogVersion = 's4-trust-pipeline-v1'
    const nowMs = Date.now()

    for (const route of routes) {
      // 1. Route must exist in curated_routes
      const curatedRoute = await ctx.db
        .query('curated_routes')
        .withIndex('by_routeId', (q) => q.eq('routeId', route.routeId))
        .first()

      if (!curatedRoute) {
        throw new ConvexError({
          code: 'ROUTE_NOT_FOUND',
          message: `Route ${route.routeId} not found in curated_routes — all sample routes must exist in the catalog`,
        })
      }

      // 2. Route must have gate-passing geometry
      const geom = await ctx.db
        .query('curated_route_geometry')
        .withIndex('by_routeId', (q) => q.eq('routeId', route.routeId))
        .first()

      if (!geom) {
        throw new ConvexError({
          code: 'GEOMETRY_NOT_FOUND',
          message: `Route ${route.routeId} has no curated_route_geometry record`,
        })
      }

      const verdict = geom?.verification?.verdict
      if (verdict !== 'pass') {
        throw new ConvexError({
          code: 'GEOMETRY_NOT_GATE_PASSING',
          message: `Route ${route.routeId} geometry verdict is '${verdict ?? 'missing'}', not 'pass' — all sample routes must have gate-passing geometry`,
        })
      }

      // 3. Compute per-route geometry hash
      routeGeometryHashes[route.routeId] = computeRouteGeometryHash(route.routeId, geom)
    }

    // FIX-10: Compute manifest hash server-side
    const manifestHash = await computeManifestHash(routes, routeGeometryHashes, catalogVersion)

    // FIX-10: Freeze the manifest immediately
    const doc = {
      sampleId,
      size: routes.length,
      routes,
      createdAt: existing?.createdAt ?? nowMs,
      manifestHash,
      catalogVersion,
      status: 'frozen' as const,
      frozenAt: nowMs,
      frozenBy: identity.clerkUserId,
    }

    if (existing) {
      await ctx.db.replace(existing._id, doc)
      return { sampleId, size: routes.length, replaced: true, manifestHash, status: 'frozen' }
    }
    await ctx.db.insert('couch_samples', doc)
    return { sampleId, size: routes.length, replaced: false, manifestHash, status: 'frozen' }
  },
})

// ---------------------------------------------------------------------------
// Assemble + export actions
// ---------------------------------------------------------------------------

export const assembleCouchSample = action({
  args: {
    targetSize: v.optional(v.number()),
    routeIdPrefix: v.optional(v.string()),
    sampleId: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    await requireIdentity(ctx)
    const targetSize = args.targetSize ?? COUCH_SAMPLE_TARGET
    // Default: include PRD fixtures + couch-prefixed seeds
    const listed = await ctx.runQuery(api.couchSampleAssembler.listRecoveredCandidates, {
      // Empty prefix → listRecoveredCandidates returns all generated; we filter below
      limit: 400,
    })

    // Prefer couch test fixtures when present; fall back to full catalog
    let pool = (listed.candidates as CouchSampleRoute[]).filter(
      (c) =>
        c.routeId.startsWith(COUCH_ROUTE_PREFIX) ||
        c.routeId.startsWith('test:scraped-') ||
        c.routeId.startsWith('test:ai-recon-') ||
        c.routeId.startsWith('test:name-routed-') ||
        (args.routeIdPrefix != null && c.routeId.startsWith(args.routeIdPrefix)),
    )
    if (pool.length < COUCH_SAMPLE_MIN) {
      pool = listed.candidates as CouchSampleRoute[]
    }

    const routes = stratifyCouchSample(pool, targetSize)
    if (routes.length < COUCH_SAMPLE_MIN) {
      throw new ConvexError({
        code: 'INSUFFICIENT_CANDIDATES',
        message: `Need ≥${COUCH_SAMPLE_MIN} recovered candidates for couch sample, got ${routes.length}`,
      })
    }

    const sampleId = args.sampleId ?? `couch-${Date.now()}`
    await ctx.runMutation(api.couchSampleAssembler.storeCouchSample, {
      sampleId,
      routes,
    })

    const counts = {
      scraped_promoted: routes.filter((r) => r.provenance === 'scraped_promoted').length,
      ai_reconstructed: routes.filter((r) => r.provenance === 'ai_reconstructed').length,
      name_routed: routes.filter((r) => r.provenance === 'name_routed').length,
    }

    return {
      sampleId,
      size: routes.length,
      routes,
      counts,
    }
  },
})

/**
 * Look up encoded polylines for export rendering.
 * Prefers curated_route_geometry.value, falls back to curated_routes.routePolyline.
 */
export const getGeometriesForRoutes = query({
  args: {
    routeIds: v.array(v.string()),
  },
  handler: async (ctx, { routeIds }) => {
    await requireIdentity(ctx)
    const out: Record<string, string> = {}
    for (const routeId of routeIds) {
      const geom = await ctx.db
        .query('curated_route_geometry')
        .withIndex('by_routeId', (q) => q.eq('routeId', routeId))
        .first()
      if (geom?.value && typeof geom.value === 'string' && geom.value.length > 0) {
        out[routeId] = geom.value
        continue
      }
      const route = await ctx.db
        .query('curated_routes')
        .withIndex('by_routeId', (q) => q.eq('routeId', routeId))
        .first()
      if (route?.routePolyline && typeof route.routePolyline === 'string') {
        out[routeId] = route.routePolyline
      }
    }
    return out
  },
})

// exportCouchSample lives in couchSampleExport.ts ("use node") so Node zlib can
// compress PNG IDAT — uncompressed 25×240² RGBA maps OOM the 64MB isolate.

