    // null early-return, making the skip unobservable.
    const claimedMiles = route.lengthMiles
    const quarantined = route.quarantine != null

    type PipelineAttempt = Awaited<ReturnType<typeof evaluateRoutedAnchors>> & {
      geocodeLog: string[]
    }

